{
  "action": "write_file",
  "path": "truncate.test.js",
  "content": "'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { truncate } = require('./truncate');

test('short text is unchanged', () => {
  assert.equal(truncate('hello', 10), 'hello');
  assert.equal(truncate('hello', 5), 'hello');
});

test('cuts at a word boundary', () => {
  assert.equal(truncate('the quick brown fox', 12), 'the quick…');
});

test('hard cut when no word boundary within max', () => {
  // max = 5, ellipsis = '…' (len 1). targetMaxPrefixLen = 4.
  // text = 'abcdef', len 6 > 5.
  // Prefixes up length 4: 'abcd'. No word boundary (no whitespace). Hard cut to 4 chars + '…'.
  assert.equal(truncate('abcdef', 5), 'abcd…');
});

test('whitespace types as boundaries (spaces, tabs, newlines)', () => {
  assert.equal(truncate('the\tquick brown', 12), 'the\tquick…');
  assert.equal(truncate('the\nquick brown', 12), 'the\nquick…');
});

test('validation errors', () => {
  assert.throws(() => truncate(123, 10), TypeError);
  assert.throws(() => truncate('hello', '10'), TypeError);
  assert.throws(() => truncate('hello', 5, 123), TypeError);
  assert.throws(() => truncate('hello', 0), RangeError);
  assert.throws(() => truncate('hello', 2, '...'), RangeError);
});

test('custom ellipsis', () => {
  assert.equal(truncate('the quick brown fox', 12, '...'), 'the quic...');
});
"
}
